+	l = le->link;
+	if (!l) {
+		tipc_node_write_unlock(n);
+		return;
+	}
+
 	if (!tipc_link_is_establishing(l)) {
 		__tipc_node_link_down(n, &bearer_id, &xmitq, &maddr);
