-	if (IS_SHA256(flags))
-		cfg |= AUTH_MODE_HASH << AUTH_MODE_SHIFT;
-	else if (IS_SHA256_HMAC(flags))
-		cfg |= AUTH_MODE_HMAC << AUTH_MODE_SHIFT;
-	else if (IS_CCM(flags))
-		cfg |= AUTH_MODE_CCM << AUTH_MODE_SHIFT;
