-static int qce_ahash_update(struct ahash_request *req)
-{
-	struct crypto_ahash *tfm = crypto_ahash_reqtfm(req);
-	struct qce_sha_reqctx *rctx = ahash_request_ctx_dma(req);
-	struct qce_alg_template *tmpl = to_ahash_tmpl(req->base.tfm);
-	struct qce_device *qce = tmpl->qce;
-	unsigned int total;
-	unsigned int hash_later;
-	unsigned int blocksize;
-
-	blocksize = crypto_tfm_alg_blocksize(crypto_ahash_tfm(tfm));
-	rctx->count += req->nbytes;
-
-	/* check for buffer from previous updates and append it */
-	total = req->nbytes + rctx->buflen;
-
-	if (total <= blocksize) {
-		scatterwalk_map_and_copy(rctx->buf + rctx->buflen, req->src,
-					 0, req->nbytes, 0);
-		rctx->buflen += req->nbytes;
-		return 0;
-	}
-
-	/* save the original req structure fields */
-	rctx->src_orig = req->src;
-	rctx->nbytes_orig = req->nbytes;
-
-	/*
-	 * if we have data from previous update copy them on buffer. The old
-	 * data will be combined with current request bytes.
-	 */
-	if (rctx->buflen)
-		memcpy(rctx->tmpbuf, rctx->buf, rctx->buflen);
-
-	/* calculate how many bytes will be hashed later */
-	hash_later = total % blocksize;
-
-	/*
-	 * At this point, there is more than one block size of data.  If
-	 * the available data to transfer is exactly a multiple of block
-	 * size, save the last block to be transferred in qce_ahash_final
-	 * (with the last block bit set) if this is indeed the end of data
-	 * stream. If not this saved block will be transferred as part of
-	 * next update. If this block is not held back and if this is
-	 * indeed the end of data stream, the digest obtained will be wrong
-	 * since qce_ahash_final will see that rctx->buflen is 0 and return
-	 * doing nothing which in turn means that a digest will not be
-	 * copied to the destination result buffer.  qce_ahash_final cannot
-	 * be made to alter this behavior and allowed to proceed if
-	 * rctx->buflen is 0 because the crypto engine BAM does not allow
-	 * for zero length transfers.
-	 */
-	if (!hash_later)
-		hash_later = blocksize;
-
-	scatterwalk_map_and_copy(rctx->buf, req->src, req->nbytes - hash_later,
-				 hash_later, 0);
-
-	if (rctx->buflen) {
-		sg_init_table(rctx->sg, 2);
-		sg_set_buf(rctx->sg, rctx->tmpbuf, rctx->buflen);
-		sg_chain(rctx->sg, 2, req->src);
-		req->src = rctx->sg;
-	}
-
-	/* hash only complete blocks */
-	req->nbytes = total - hash_later;
-	rctx->buflen = hash_later;
-
-	return qce->async_req_enqueue(tmpl->qce, &req->base);
-}
-
-static int qce_ahash_final(struct ahash_request *req)
-{
-	struct qce_sha_reqctx *rctx = ahash_request_ctx_dma(req);
-	struct qce_alg_template *tmpl = to_ahash_tmpl(req->base.tfm);
-	struct qce_device *qce = tmpl->qce;
-
-	if (!rctx->buflen) {
-		if (tmpl->hash_zero)
-			memcpy(req->result, tmpl->hash_zero,
-					tmpl->alg.ahash.halg.digestsize);
-		return 0;
-	}
-
-	rctx->last_blk = true;
-
-	rctx->src_orig = req->src;
-	rctx->nbytes_orig = req->nbytes;
-
-	memcpy(rctx->tmpbuf, rctx->buf, rctx->buflen);
-	sg_init_one(rctx->sg, rctx->tmpbuf, rctx->buflen);
-
-	req->src = rctx->sg;
-	req->nbytes = rctx->buflen;
-
-	return qce->async_req_enqueue(tmpl->qce, &req->base);
-}
-
-static int qce_ahash_digest(struct ahash_request *req)
