-	rctx->src_orig = req->src;
-	rctx->nbytes_orig = req->nbytes;
-	rctx->first_blk = true;
-	rctx->last_blk = true;
-
-	if (!rctx->nbytes_orig) {
-		if (tmpl->hash_zero)
